function getYellowfinaiTranslation(key, lang) {
    if (yellowfinaiTranslations[lang] && yellowfinaiTranslations[lang][key]) {
        return yellowfinaiTranslations[lang][key];
    }
    if (yellowfinaiTranslations.en && yellowfinaiTranslations.en[key]) {
        return yellowfinaiTranslations.en[key];
    }
    return null;
}

function applyYellowfinaiTranslations(lang) {
    
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && key.startsWith('review.yellowfin-ai.')) {
            const translation = getYellowfinaiTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyYellowfinaiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyYellowfinaiTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyYellowfinaiTranslations(currentLang);
}


